    enum GlyphKind { None, Refresh, Activity, Record, Stop, Minimize, Maximize, Close, Link, Power }
    static class Glyphs {
        public static void Draw(Graphics g,GlyphKind kind,RectangleF bounds,Color color){
            GraphicsState saved=g.Save();try{g.TranslateTransform(bounds.X,bounds.Y);g.ScaleTransform(bounds.Width/24f,bounds.Height/24f);g.SmoothingMode=SmoothingMode.AntiAlias;
                using(Pen p=new Pen(color,1.8f)){p.StartCap=p.EndCap=LineCap.Round;p.LineJoin=LineJoin.Round;
                    if(kind==GlyphKind.Refresh){g.DrawArc(p,3,3,18,18,35,300);g.DrawLines(p,new PointF[]{new PointF(21,3),new PointF(21,9),new PointF(15,9)});}
                    else if(kind==GlyphKind.Activity)g.DrawLines(p,new PointF[]{new PointF(2,12),new PointF(6,12),new PointF(9,3),new PointF(15,21),new PointF(18,12),new PointF(22,12)});
                    else if(kind==GlyphKind.Power){g.DrawArc(p,3,3,18,18,-45,270);g.DrawLine(p,12,2,12,12);}
                    else if(kind==GlyphKind.Link){using(GraphicsPath path=new GraphicsPath()){path.StartFigure();path.AddBezier(10,13,11.95f,14.95f,15.12f,15.49f,17.54f,13.54f);path.AddLine(17.54f,13.54f,20.54f,10.54f);path.AddBezier(20.54f,10.54f,22.49f,8.59f,22.49f,5.42f,20.54f,3.47f);path.AddBezier(20.54f,3.47f,18.59f,1.52f,15.42f,1.52f,13.47f,3.47f);path.AddLine(13.47f,3.47f,11.75f,5.18f);path.StartFigure();path.AddBezier(14,11,12.05f,9.05f,8.88f,8.51f,6.46f,10.46f);path.AddLine(6.46f,10.46f,3.46f,13.46f);path.AddBezier(3.46f,13.46f,1.51f,15.41f,1.51f,18.58f,3.46f,20.53f);path.AddBezier(3.46f,20.53f,5.41f,22.48f,8.58f,22.48f,10.53f,20.53f);path.AddLine(10.53f,20.53f,12.24f,18.82f);g.DrawPath(p,path);}}
                    else if(kind==GlyphKind.Minimize)g.DrawLine(p,5,12,19,12);
                    else if(kind==GlyphKind.Maximize)g.DrawRectangle(p,5,5,14,14);
                    else if(kind==GlyphKind.Close){g.DrawLine(p,5,5,19,19);g.DrawLine(p,19,5,5,19);}
                    else if(kind==GlyphKind.Record)using(Brush b=new SolidBrush(color))g.FillEllipse(b,4,4,16,16);
                    else if(kind==GlyphKind.Stop)using(GraphicsPath path=Theme.Round(new Rectangle(6,6,12,12),2))using(Brush b=new SolidBrush(color))g.FillPath(b,path);
                }
            }finally{g.Restore(saved);}
        }
    }
