        void RestartListener(){sendTimer.Stop();if(recording)CancelRecording("监听重启，已取消录制。");if(mapper!=null){mapper.Dispose();mapper=null;}try{mapper=new KeyboardMapper();mapper.Enabled=settings.Enabled;mapper.Connected=device.ButtonReady;mapper.Trace=inputTrace;mapper.Pressed+=delegate{PostUI(ScheduleShortcut);};mapper.SourcePressed+=delegate{PostUI(FlashIndicator);};mapper.RecordingProgress+=delegate(string text){PostUI(delegate{if(recording)keycapPreview.KeysText=text;});};mapper.RecordingFinished+=delegate(ShortcutSpec spec,string error){PostUI(delegate{FinishRecording(spec,error);});};enableBox.Enabled=true;inputTrace.Add("LISTENER restarted");}catch(Exception ex){enableBox.Enabled=false;saveLabel.Text=ex.Message;saveLabel.ForeColor=Color.Firebrick;inputTrace.Add("LISTENER error="+Native.Error(ex));}UpdateState();}
        string DiagnosticState(){return "Enabled: "+settings.Enabled+Environment.NewLine+"HID button ready: "+device.ButtonReady+Environment.NewLine+"Audio endpoint ready: "+device.Connected+Environment.NewLine+"Capture name: "+device.Name+Environment.NewLine+"Device error: "+device.Error+Environment.NewLine+"Hook thread running: "+(mapper!=null&&mapper.IsRunning)+Environment.NewLine+"Target: "+settings.Shortcut.Display;}
        void StartTrace(){if(recording)CancelRecording("诊断开始，已取消快捷键录制。");inputTrace.Start();traceReady=false;diagnosticWindow.ClearLog();inputTrace.Add("START "+DiagnosticState().Replace(Environment.NewLine," | "));bool healthy=mapper!=null&&mapper.ProbeHealth();inputTrace.Add("HOOK probe acknowledged="+healthy+" (false can also mean injected input was blocked)");try{rawTrace=new RawControlTrace(inputTrace);}catch(Exception ex){inputTrace.Add("RAW observer error="+Native.Error(ex));}diagnosticButton.Text="结束诊断";diagnosticHint.Text="正在采集 30 秒：请按配对键 3 次。不会记录普通文字输入或保存音频。";diagnosticTimer.Start();Relayout();diagnosticWindow.TryShow(this);diagnosticButton.Text="诊断";}
        void StopTrace(){diagnosticTimer.Stop();if(!inputTrace.Active)return;inputTrace.Add("HOOK end probe acknowledged="+(mapper!=null&&mapper.ProbeHealth()));inputTrace.Add("END "+DiagnosticState().Replace(Environment.NewLine," | "));traceReport=InputTrace.EnvironmentReport()+Environment.NewLine+"Started UTC: "+inputTrace.Started.ToString("o")+Environment.NewLine+inputTrace.Stop();diagnosticWindow.AppendLog("END");if(rawTrace!=null){rawTrace.Dispose();rawTrace=null;}traceReady=true;diagnosticHint.Text="诊断已结束；如需保存记录，请再次点击“诊断”。";Relayout();}
        void ExportTrace(){if(inputTrace.Active)StopTrace();using(SaveFileDialog dialog=new SaveFileDialog{Title="保存按键诊断报告",Filter="文本文件|*.txt",FileName="DJIMicKey-diagnostics-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".txt"}){if(dialog.ShowDialog(diagnosticWindow.Visible?(IWin32Window)diagnosticWindow:(IWin32Window)this)!=DialogResult.OK)return;try{File.WriteAllText(dialog.FileName,traceReport,System.Text.Encoding.UTF8);traceReady=false;diagnosticButton.Text="开始按键诊断";diagnosticHint.Text="报告已保存。可比较普通权限与管理员权限下的结果。";}catch(Exception ex){diagnosticHint.Text="保存失败："+ex.Message;}}Relayout();}
                void PostUI(Action action){if(IsDisposed||Disposing||!IsHandleCreated)return;try{BeginInvoke(action);}catch(InvalidOperationException){}}
        void SetRecordState(RecordState next){recordState=next;recordButton.Text=next==RecordState.Recording?"取消录制":next==RecordState.PendingApply?"应用并保存":"开始录制";recordButton.BackColor=next==RecordState.Recording?Theme.Danger:Theme.Blue;recordButton.FlatAppearance.BorderColor=recordButton.BackColor;((RoundedButton)recordButton).Glyph=next==RecordState.Idle?GlyphKind.Record:GlyphKind.Stop;enableBox.Enabled=next!=RecordState.Recording&&mapper!=null;if(trayToggle!=null)trayToggle.Enabled=next!=RecordState.Recording;}
        void StartRecording(){if(mapper==null)return;SetRecordState(RecordState.Recording);sendTimer.Stop();mapper.StartRecording();keycapPreview.KeysText="请按下快捷键…";saveLabel.Text="正在录制；松开所有按键后确认保存，Esc 可取消。";saveLabel.ForeColor=Theme.Muted;recordTimer.Start();}
        void CancelRecording(string text){if(!recording)return;mapper.CancelRecording();FinishRecording(null,text);}
        void FinishRecording(ShortcutSpec spec,string error){if(!recording)return;recordTimer.Stop();if(spec!=null){draftShortcut=spec.Copy();SetRecordState(RecordState.PendingApply);saveLabel.Text="已录制，点击“应用并保存”后生效。";saveLabel.ForeColor=Theme.Green;}else{draftShortcut=settings.Shortcut.Copy();SetRecordState(RecordState.Idle);saveLabel.Text=error;saveLabel.ForeColor=Theme.Muted;}keycapPreview.KeysText=draftShortcut.Display;}
        void ApplyShortcut(){if(!draftReady)return;try{draftShortcut.Validate();Settings proposed=new Settings{Shortcut=draftShortcut.Copy(),Enabled=settings.Enabled,CompatibilityMode=settings.CompatibilityMode};proposed.Save(SettingsPathForTest??Settings.FilePath);sendTimer.Stop();settings.Shortcut=proposed.Shortcut;keycapPreview.KeysText=settings.Shortcut.Display;SetRecordState(RecordState.Idle);saveLabel.Text="快捷键已保存；请在输入法中设置相同组合。";saveLabel.ForeColor=Theme.Green;}catch(Exception ex){SetRecordState(RecordState.PendingApply);saveLabel.Text="保存失败，请重试："+ex.Message;saveLabel.ForeColor=Color.Firebrick;}}
        void SaveSettings(){try{settings.Save(SettingsPathForTest??Settings.FilePath);saveLabel.Text="已保存。请让输入法的语音快捷键与上方组合一致。";saveLabel.ForeColor=Theme.Green;}catch(Exception ex){saveLabel.Text="当前已生效，但保存失败："+ex.Message;saveLabel.ForeColor=Color.Firebrick;}}
        void RefreshDevices(){if(quitting)return;device=DeviceProbe.Scan();if(mapper!=null)mapper.Connected=device.ButtonReady;
            if(device.Connected){deviceLabel.Text="DJI Mic Mini 接收器已连接";deviceLabel.ForeColor=Theme.Ink;deviceDetail.Text=device.Name+" · USB 2CA3:4011";}
            else{deviceLabel.Text=device.Hid?"接收器已识别，音频接口未就绪":"未检测到 DJI Mic Mini 接收器";deviceLabel.ForeColor=device.Hid?Color.DarkOrange:Theme.Muted;deviceDetail.Text=device.Error.Length>0?"检测失败："+device.Error:"请连接 USB 接收器；发射器无线链路需通过说话测试确认。";sendTimer.Stop();}
            UpdateAudio();UpdateState();
        }
        void RefreshFooter(){if(statusFooter==null)return;bool healthy=previewMode||(mapper!=null&&mapper.IsRunning),active=previewMode||(healthy&&settings.Enabled&&device.ButtonReady);statusFooter.Ready=healthy;statusFooter.Active=active;statusFooter.Listener=healthy?"快捷键监听已就绪":"快捷键监听未就绪";statusFooter.Mapping=active?"映射已启用":settings.Enabled?"等待连接":"映射已暂停";statusFooter.Hits=hits;if(lastLabel.Text.StartsWith("已触发 ",StringComparison.Ordinal)){int marker=lastLabel.Text.LastIndexOf("最近 ",StringComparison.Ordinal);if(marker>=0)statusFooter.Recent=lastLabel.Text.Substring(marker+3);statusFooter.Error="";}else if(lastLabel.Text=="尚未触发。")statusFooter.Error="";else statusFooter.Error=lastLabel.Text;statusFooter.Invalidate();if(statusFooter.RequiredHeight(canvas.Width)!=statusFooter.Height)Relayout();}
        void UpdateState(){bool active=mapper!=null&&mapper.IsRunning&&mapper.Enabled&&device.ButtonReady;mappingState.Text=mapper!=null&&!mapper.IsRunning?"按键监听已停止，请点击“重启按键监听”":active?"映射已启用  ·  键盘音量加键也会被映射":(enableBox.Checked?"等待接收器连接，当前保留音量加功能":"映射已暂停，当前保留音量加功能");mappingState.ForeColor=active?Theme.Green:Theme.Muted;if(trayToggle!=null)trayToggle.Text=enableBox.Checked?"暂停映射":"启用映射";RefreshFooter();if(tray!=null)tray.Text=active?"DJI Mic Key · 映射已启用":"DJI Mic Key · 映射未生效";}
        void UpdateAudio(){if(!ready)return;bool shouldRun=testing&&!backgroundMode&&device.Connected&&Visible&&WindowState!=FormWindowState.Minimized&&!quitting;
            testButton.Text=testing?"停止测试":"启动测试";testButton.Enabled=device.Connected;
            if(!shouldRun){StopAudio();dbLabel.Text="— dBFS";meterHint.Text=!device.Connected?"连接接收器后，对着麦克风说话测试。":(testing?"窗口已隐藏，音量检测已暂停。":"测试已暂停，点击“开始测试”查看输入电平。");return;}
            if(audio!=null&&audio.EndpointId!=device.EndpointId)StopAudio();
            if(audio==null){try{audio=new AudioMonitor(device.EndpointId);monitorError="";}catch(Exception ex){StopAudio();monitorError=Native.Error(ex);dbLabel.Text="读取失败";meterHint.Text="无法读取麦克风："+monitorError;return;}}
            meterTimer.Start();meterHint.Text="请说话测试。仅显示电平，不保存或上传音频。";
        }
        void StopAudio(){meterTimer.Stop();if(audio!=null){audio.Dispose();audio=null;}bar.Reset();waveform.Reset();}
        void PollAudio(){if(audio==null)return;try{float peak=audio.Poll();bar.SetLevel(peak);waveform.AddLevel(bar.DisplayLevel);double db=peak>0?20*Math.Log10(peak):-90;string text=db<=-60?"< −60 dBFS":db.ToString("0.0")+" dBFS";if(dbLabel.Text!=text)dbLabel.Text=text;if(db>-3)meterHint.Text="输入接近峰值，请降低麦克风增益或远离嘴部。";else if(meterHint.Text.IndexOf("无法读取",StringComparison.Ordinal)<0)meterHint.Text="请说话测试。仅显示电平，不保存或上传音频。";}catch(Exception ex){StopAudio();meterHint.Text="麦克风不可用："+Native.Error(ex);dbLabel.Text="读取失败";}}
        void FlashIndicator(){if(quitting||!Visible||WindowState==FormWindowState.Minimized)return;devicePreview.Lit=true;devicePreview.Invalidate();indicatorTimer.Stop();indicatorTimer.Start();}
        void ResetIndicator(){indicatorTimer.Stop();if(devicePreview!=null&&devicePreview.Lit){devicePreview.Lit=false;devicePreview.Invalidate();}}
        void ScheduleShortcut(){if(quitting||recording||sendTimer.Enabled)return;sendAttempts=0;sendTimer.Start();}
        void DispatchShortcut(){sendTimer.Stop();if(quitting||recording||mapper==null||!mapper.Enabled||!device.ButtonReady)return;
            // Avoid combining the target with modifiers the user is holding.
            if(ShortcutSpec.OtherKeysHeld()){if(++sendAttempts<12){sendTimer.Start();return;}lastLabel.Text="已跳过：请松开键盘上的 Ctrl / Alt / Shift / Win 后重试。";return;}
            try{inputTrace.Add("SEND attempt target="+settings.Shortcut.Display);settings.Shortcut.Send();inputTrace.Add("SEND accepted by Windows (not a recognition acknowledgement)");hits++;lastLabel.Text="已触发 "+hits+" 次  ·  最近 "+DateTime.Now.ToString("HH:mm:ss");}catch(Exception ex){inputTrace.Add("SEND error="+Native.Error(ex));lastLabel.Text=ex.Message;}
        }
        public void ExerciseRecordingForTest(){if(mapper==null)throw new Exception("Recorder hook unavailable");string directory=Path.Combine(Path.GetTempPath(),"DJIMicKey-ui-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(directory);SettingsPathForTest=Path.Combine(directory,"settings.ini");try{string original=settings.Shortcut.Display;recordButton.PerformClick();if(!recording)throw new Exception("Recording did not start");ShortcutSpec sample=ShortcutSpec.FromKeys(new ushort[]{0xA3,0xA5,0x86});Native.Input[] input=sample.BuildInput();for(int i=0;i<input.Length;i++)input[i].data.keyboard.extra=UIntPtr.Zero;Native.SendInput((uint)input.Length,input,System.Runtime.InteropServices.Marshal.SizeOf(typeof(Native.Input)));Stopwatch wait=Stopwatch.StartNew();while(recording&&wait.ElapsedMilliseconds<1500){Application.DoEvents();Thread.Sleep(5);}if(recording||draftShortcut.Display!=sample.Display)throw new Exception("Captured chord mismatch");if(settings.Shortcut.Display!=original||!draftReady)throw new Exception("Capture committed without Save");string normalPath=SettingsPathForTest,badPath=Path.Combine(directory,"directory-as-file");Directory.CreateDirectory(badPath);try{SettingsPathForTest=badPath;recordButton.PerformClick();if(!draftReady||settings.Shortcut.Display!=original||saveLabel.Text.IndexOf("保存失败",StringComparison.Ordinal)<0)throw new Exception("Failed persistence did not retain draft and previous shortcut");}finally{if(File.Exists(badPath+".tmp"))File.Delete(badPath+".tmp");Directory.Delete(badPath);SettingsPathForTest=normalPath;}recordButton.PerformClick();if(settings.Shortcut.Display!=sample.Display||Settings.Load(SettingsPathForTest).Shortcut.Display!=sample.Display)throw new Exception("Save and finish did not persist the chord");recordButton.PerformClick();if(!recording)throw new Exception("Second recording did not start");CancelRecording("Test cancellation");if(recording||settings.Shortcut.Display!=sample.Display)throw new Exception("Cancel changed the saved shortcut");}finally{if(File.Exists(SettingsPathForTest))File.Delete(SettingsPathForTest);Directory.Delete(directory);SettingsPathForTest=null;}}
        public void ExerciseDiagnosticsForTest(string output){
