                diagnosticWindow.WhenShownForTest=delegate{inputTrace.Add("TEST diagnostic checkpoint");Native.SendMessage(diagnosticWindow.Handle,0x0112,new IntPtr(0xF030),IntPtr.Zero);Native.SendMessage(diagnosticWindow.Handle,0x00A3,new IntPtr(2),IntPtr.Zero);diagnosticWindow.WindowState=FormWindowState.Maximized;Application.DoEvents();if(diagnosticWindow.WindowState!=FormWindowState.Normal||diagnosticWindow.MaximizeBox)throw new Exception("Diagnostic window accepted maximization");diagnosticWindow.Close();};StartTrace();Application.DoEvents();diagnosticWindow.WhenShownForTest=null;if(inputTrace.Active||!traceReady||rawTrace!=null)throw new Exception("Modal diagnostic did not stop and release its observer");if(traceReport.IndexOf("TEST diagnostic checkpoint",StringComparison.Ordinal)<0||traceReport.IndexOf("HOOK probe acknowledged=True",StringComparison.Ordinal)<0||diagnosticWindow.LogText.IndexOf("TEST diagnostic checkpoint",StringComparison.Ordinal)<0)throw new Exception("Diagnostic capture or live modal output missing");
