            }
            Native.SendMessage(Handle,0x0112,new IntPtr(0xF020),IntPtr.Zero);Application.DoEvents();Native.SendMessage(Handle,0x0112,new IntPtr(0xF120),IntPtr.Zero);Application.DoEvents();if(WindowState!=FormWindowState.Normal)throw new Exception("Native taskbar restore failed");Stopwatch settle=Stopwatch.StartNew();while(settle.ElapsedMilliseconds<250){Application.DoEvents();Thread.Sleep(10);}SyncShadow();if(shadow.Bounds!=Rectangle.Inflate(Bounds,D(16),D(16)))throw new Exception("Shadow did not follow restored bounds");
            using(Bitmap restored=new Bitmap(ClientSize.Width,ClientSize.Height)){using(Graphics graphics=Graphics.FromImage(restored))graphics.CopyFromScreen(PointToScreen(Point.Empty),Point.Empty,restored.Size);if(restored.GetPixel(ClientSize.Width/2,D(10)).ToArgb()!=Color.White.ToArgb())throw new Exception("Restored header is not visible on screen");restored.Save(Path.ChangeExtension(output,".png"),System.Drawing.Imaging.ImageFormat.Png);}
            File.WriteAllText(output,traceReport+Environment.NewLine+"PASS: three modal cycles reject maximize and title double-click; minimize/restore retains enabled content, borderless styles and client bounds");RestartListener();if(mapper==null||!mapper.ProbeHealth())throw new Exception("Listener restart failed");
        }
