        void ValidateChildren(Control parent){List<Control> children=new List<Control>();foreach(Control control in parent.Controls){if(!control.Visible)continue;children.Add(control);if(control.Left<0||control.Top<0||control.Right>parent.ClientSize.Width||control.Bottom>parent.ClientSize.Height)throw new Exception("Control escapes parent: "+control.Text);Label label=control as Label;if(label!=null&&label.Height<TextHeight(label,label.Width))throw new Exception("Clipped label: "+label.Text);Button button=control as Button;if(button!=null&&(button.Width<NaturalWidth(button)+D(12)||button.Height<button.Font.Height+D(8)))throw new Exception("Clipped button: "+button.Text);if(control is Panel)ValidateChildren(control);}for(int i=0;i<children.Count;i++)for(int j=i+1;j<children.Count;j++)if(children[i].Bounds.IntersectsWith(children[j].Bounds))throw new Exception("Overlapping controls: "+children[i].Text+" / "+children[j].Text);}
