        public void ExerciseFeedbackForTest(string directory){
            Directory.CreateDirectory(directory);System.Text.StringBuilder report=new System.Text.StringBuilder();using(Bitmap mask=ShadowWindow.MakeBitmap(new Size(120,80),16)){for(int d=0;d<16;d++){int top=mask.GetPixel(mask.Width/2,d).A;if(top!=mask.GetPixel(mask.Width/2,mask.Height-1-d).A||top!=mask.GetPixel(d,mask.Height/2).A||top!=mask.GetPixel(mask.Width-1-d,mask.Height/2).A)throw new Exception("Asymmetric shadow mask");}if(mask.GetPixel(mask.Width/2,mask.Height/2).A!=0)throw new Exception("Shadow covers content");}if(!shadow.ImageReady)throw new Exception("Shadow not initialized");report.AppendLine("PASS: four shadow edges have identical alpha; content is transparent");
