            try{for(int i=0;i<6;i++){hits=i;lastLabel.Text="已触发 "+i+" 次  ·  最近 12:00:0"+i;RefreshFooter();Application.DoEvents();}if(waveformPaints!=0||canvasPaints!=0)throw new Exception("Footer updates repainted unrelated content: "+waveformPaints+" / "+canvasPaints);report.AppendLine("PASS: footer updates do not repaint the waveform or canvas");}finally{waveform.Paint-=wavePaint;canvas.Paint-=backgroundPaint;}
            Native.HookProc guard=delegate(int code,IntPtr message,IntPtr data){if(code>=0){Native.Kbd k=(Native.Kbd)System.Runtime.InteropServices.Marshal.PtrToStructure(data,typeof(Native.Kbd));if(k.vk==0xAF)return new IntPtr(1);}return Native.CallNextHookEx(IntPtr.Zero,code,message,data);};IntPtr guardHook=Native.SetWindowsHookEx(13,guard,Native.GetModuleHandle(null),0);if(guardHook==IntPtr.Zero)throw new Exception("Media event safety hook unavailable");
            try{using(KeyboardMapper observer=new KeyboardMapper()){int presses=0;observer.Connected=true;observer.Enabled=false;observer.SourcePressed+=delegate{System.Threading.Interlocked.Increment(ref presses);PostUI(FlashIndicator);};Native.Input down=new Native.Input();down.type=1;down.data.keyboard=new Native.KeyboardInput{vk=0xAF,scan=0,flags=1,extra=UIntPtr.Zero};Native.Input up=down;up.data.keyboard.flags=3;if(Native.SendInput(3,new[]{down,down,up},System.Runtime.InteropServices.Marshal.SizeOf(typeof(Native.Input)))!=3)throw new Exception("Source injection failed");Stopwatch wait=Stopwatch.StartNew();while(!devicePreview.Lit&&wait.ElapsedMilliseconds<1000){Application.DoEvents();Thread.Sleep(5);}if(!devicePreview.Lit||presses!=1)throw new Exception("Media key did not light the indicator once on down");report.AppendLine("PASS: Windows source-key down lights LED, ignores repeat and works with mapping paused");
                Update();Application.DoEvents();using(Bitmap bitmap=new Bitmap(Width+48,Height+48)){using(Graphics graphics=Graphics.FromImage(bitmap))graphics.CopyFromScreen(new Point(Left-24,Top-24),Point.Empty,bitmap.Size);bitmap.Save(Path.Combine(directory,"shadow-and-led.png"),System.Drawing.Imaging.ImageFormat.Png);}wait.Restart();while(indicatorTimer.Enabled&&wait.ElapsedMilliseconds<1000){Application.DoEvents();Thread.Sleep(10);}if(devicePreview.Lit||indicatorTimer.Enabled)throw new Exception("LED did not turn off and stop its timer");report.AppendLine("PASS: LED automatically turns off and stops the timer");FlashIndicator();Thread.Sleep(180);FlashIndicator();wait.Restart();while(wait.ElapsedMilliseconds<190){Application.DoEvents();Thread.Sleep(10);}if(!devicePreview.Lit)throw new Exception("New press did not extend the pulse");Hide();Application.DoEvents();if(devicePreview.Lit||indicatorTimer.Enabled)throw new Exception("Hidden window retained pulse work");Show();Application.DoEvents();report.AppendLine("PASS: repeated presses extend pulse; hiding clears it without background timer");}}
            finally{Native.UnhookWindowsHookEx(guardHook);GC.KeepAlive(guard);ResetIndicator();}File.WriteAllText(Path.Combine(directory,"report.txt"),report.ToString());
        }
