        protected override void WndProc(ref Message m){if(m.Msg==0x007C&&m.WParam.ToInt64()==-16){int style=System.Runtime.InteropServices.Marshal.ReadInt32(m.LParam,4);System.Runtime.InteropServices.Marshal.WriteInt32(m.LParam,4,style&~(0x00C00000|0x00040000|0x00010000));}if(m.Msg==0x0084&&FormBorderStyle==FormBorderStyle.None){IntPtr hit=HitTestBorder();if(hit!=IntPtr.Zero){m.Result=hit;return;}}if(m.Msg==0x0319&&inputTrace.Active)inputTrace.Add("WM_APPCOMMAND command="+InputTrace.AppCommand(m.LParam)+" device="+InputTrace.AppCommandDevice(m.WParam)+" keyState="+InputTrace.AppCommandKeyState(m.LParam));if((uint)m.Msg==Program.ShowMessage){ShowWindow();return;}if((uint)m.Msg==Program.QuitMessage){Quit();return;}if((uint)m.Msg==Program.StartDiagnosticMessage){if(!Visible)ShowWindow();if(!inputTrace.Active){traceReady=false;diagnosticButton.Text="诊断";StartTrace();}return;}if(m.Msg==0x02E0&&layoutReady){uiDpi=(int)(m.WParam.ToInt64()&65535);if(m.LParam!=IntPtr.Zero){Native.Rect rect=(Native.Rect)System.Runtime.InteropServices.Marshal.PtrToStructure(m.LParam,typeof(Native.Rect));Bounds=Rectangle.FromLTRB(rect.Left,rect.Top,rect.Right,rect.Bottom);}RefreshFonts();m.Result=IntPtr.Zero;return;}base.WndProc(ref m);if(m.Msg==0x0005&&layoutReady)PostUI(SyncShadow);if(m.Msg==0x001A&&layoutReady)PostUI(RefreshFonts);if(m.Msg==Native.WM_DEVICECHANGE&&ready){deviceTimer.Stop();deviceTimer.Interval=300;EventHandler handler=null;handler=delegate{deviceTimer.Tick-=handler;deviceTimer.Interval=3000;};deviceTimer.Tick+=handler;deviceTimer.Start();}}
        protected override void OnFormClosing(FormClosingEventArgs e){if(!quitting&&!previewMode&&e.CloseReason==CloseReason.UserClosing){if(choosingClose){e.Cancel=true;return;}if(recording)CancelRecording("已取消录制。");CloseChoice choice;choosingClose=true;try{choice=AskCloseChoice();}finally{choosingClose=false;}if(!quitting){if(choice==CloseChoice.Tray){e.Cancel=true;MinimizeToTray();return;}if(choice!=CloseChoice.Exit){e.Cancel=true;return;}}}quitting=true;shadow.Hide();diagnosticTimer.Stop();ResetIndicator();inputTrace.Active=false;if(rawTrace!=null){rawTrace.Dispose();rawTrace=null;}if(diagnosticWindow!=null&&diagnosticWindow.Visible)diagnosticWindow.Close();recordTimer.Stop();if(mapper!=null)mapper.CancelRecording();deviceTimer.Stop();sendTimer.Stop();StopAudio();if(mapper!=null){mapper.Dispose();mapper=null;}if(tray!=null){tray.Visible=false;tray.Dispose();tray=null;}base.OnFormClosing(e);}
        protected override void Dispose(bool disposing){if(disposing){shadow.Dispose();tips.Dispose();deviceTimer.Dispose();meterTimer.Dispose();sendTimer.Dispose();recordTimer.Dispose();diagnosticTimer.Dispose();indicatorTimer.Dispose();if(rawTrace!=null)rawTrace.Dispose();if(audio!=null)audio.Dispose();if(mapper!=null)mapper.Dispose();if(tray!=null)tray.Dispose();if(Icon!=null)Icon.Dispose();if(diagnosticWindow!=null)diagnosticWindow.Dispose();}base.Dispose(disposing);if(disposing){foreach(Font font in fontCache.Values)font.Dispose();fontCache.Clear();}}
