            Native.EnableMonitorDpi();Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);
            if(args.Length>1&&args[0]=="--layout-smoke"){Directory.CreateDirectory(args[1]);System.Text.StringBuilder report=new System.Text.StringBuilder();try{using(MainForm form=new MainForm(new Settings(),true)){form.Show();Application.DoEvents();foreach(int dpi in new int[]{96,120,144,168,192})foreach(bool compatible in new bool[]{true}){form.SetLayoutForTest(dpi,compatible,1,740);form.ValidateLayoutForTest();string name="auto-"+(dpi*100/96);form.RenderContentForTest(Path.Combine(args[1],name+".png"));report.AppendLine("PASS: "+name);}form.SetLongTextForTest();foreach(int dpi in new int[]{96,144,192}){form.SetLayoutForTest(dpi,true,1.35f,480);form.ValidateLayoutForTest();form.RenderContentForTest(Path.Combine(args[1],"large-text-"+(dpi*100/96)+".png"));report.AppendLine("PASS: enlarged fonts / narrow width at "+dpi+" DPI");}foreach(int dpi in new int[]{192,96,144,120,192,96}){form.SetLayoutForTest(dpi,false,1,740);form.ValidateLayoutForTest();}report.AppendLine("PASS: repeated DPI transitions without cumulative scaling");form.ExerciseDpiMessagesForTest();report.AppendLine("PASS: WM_DPICHANGED handler resizes and replaces font scale correctly");form.Quit();}foreach(int dpi in new int[]{96,144,192})foreach(bool compatible in new bool[]{false,true}){using(CloseChoiceDialog dialog=new CloseChoiceDialog(dpi,compatible,new Rectangle(0,0,1920,1080))){dialog.Show();Application.DoEvents();dialog.ValidateForTest();dialog.RenderForTest(Path.Combine(args[1],"close-"+(compatible?"compat":"normal")+"-"+(dpi*100/96)+".png"));dialog.Close();}report.AppendLine("PASS: close dialog layout at "+dpi+" DPI, compatibility="+compatible);}File.WriteAllText(Path.Combine(args[1],"report.txt"),report.ToString());return 0;}catch(Exception ex){report.AppendLine(ex.ToString());File.WriteAllText(Path.Combine(args[1],"report.txt"),report.ToString());return 1;}}
