            if(args.Length>1&&args[0]=="--input-diagnostic-smoke"){try{using(MainForm form=new MainForm(new Settings(),false)){form.Show();Application.DoEvents();try{form.ExerciseDiagnosticsForTest(args[1]);}finally{form.Quit();}}return 0;}catch(Exception ex){File.WriteAllText(args[1],ex.ToString());return 1;}}
