t opened audio capture");report.AppendLine("PASS: autostart hides to tray without audio capture");form.ShowWindow();Application.DoEvents();form.Quit();if(!form.ResourcesReleased)throw new Exception("Explicit quit leaked resources");report.AppendLine("PASS: explicit Quit exits without a redundant prompt");}using(MainForm form=new MainForm(new Settings(),false)){form.CloseDialogShownForTest=delegate{form.Quit();};form.Show();Application.DoEvents();form.Close();if(!form.IsDisposed||!form.ResourcesReleased)throw new Exception("Quit while close dialog is open did not finish");report.AppendLine("PASS: Quit while the close dialog is open exits cleanly");}File.WriteAllText(args[1],report.ToString());return 0;}catch(Exception ex){File.WriteAllText(args[1],report.ToString()+ex);return 1;}}
            if(args.Length>1&&args[0]=="--render-diagnostic-preview"){using(DiagnosticWindow form=new DiagnosticWindow(96,false,Screen.PrimaryScreen.WorkingArea)){form.Show();form.AppendLog("等待接收器事件 · 仅显示真实媒体键与 DJI HID 报告");Application.DoEvents();using(Bitmap bitmap=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bitmap,new Rectangle(Point.Empty,bitmap.Size));bitmap.Save(args[1],System.Drawing.Imaging.ImageFormat.Png);}form.Close();}return 0;}
            if(args.Length>1&&args[0]=="--make-icon"){using(Icon icon=Theme.CreateIcon())using(FileStream stream=File.Create(args[1]))icon.Save(stream);return 0;}
            if(args.Length>1&&args[0]=="--record-smoke"){int escaped=0;Native.HookProc guard=delegate(int code,IntPtr message,IntPtr data){if(code>=0){Native.Kbd key=(Native.Kbd)System.Runtime.InteropServices.Marshal.PtrToStructure(data,typeof(Native.Kbd));if(key.vk==0xA3||key.vk==0xA5||key.vk==0x86){escaped++;return new IntPtr(1);}}return Native.CallNextHookEx(IntPtr.Zero,code,message,data);};IntPtr guardHook=Native.SetWindowsHookEx(13,guard,Native.GetModuleHandle(null),0);if(guardHook==IntPtr.Zero)throw new Exception("Recording safety hook unavailable");try{using(MainForm form=new MainForm(new Settings(),false)){form.Show();Application.DoEvents();try{form.ExerciseRecordingForTest();if(escaped!=0)throw new Exception("Recording leaked keystrokes to other applications");File.WriteAllText(args[1],"PASS: native key recording, modifier sides, save required, cancellation, and input suppression"+Environment.NewLine+form.Snapshot());}finally{form.Quit();}}return 0;}catch(Exception ex){File.WriteAllText(args[1],ex.ToString());return 1;}finally{Native.UnhookWindowsHookEx(guardHook);GC.KeepAlive(guard);}}
            if(args.Length>1&&args[0]=="--ui-smoke"){using(MainForm form=new MainForm(new Settings(),false)){form.Show();Stopwatch watch=Stopwatch.StartNew();while(watch.ElapsedMilliseconds<700){Application.DoEvents();Thread.Sleep(10);}string result="VISIBLE"+Environment.NewLine+form.Snapshot();form.Hide();Application.DoEvents();result+=Environment.NewLine+"HIDDEN"+Environment.NewLine+form.Snapshot();File.WriteAllText(args[1],result);form.Quit();}return 0;}
            if(args.Length>1&&args[0]=="--feedback-smoke"){try{using(Form backdrop=new Form{FormBorderStyle=FormBorderStyle.None,BackColor=Color.White,StartPosition=FormStartPosition.Manual,Bounds=Screen.PrimaryScreen.WorkingArea}){backdrop.Show();using(MainForm form=new MainForm(new Settings(),true)){form.Show();form.Activate();Application.DoEvents();Thread.Sleep(180);Application.DoEvents();form.ExerciseFeedbackForTest(args[1]);form.Quit();}backdrop.Close();}return 0;}catch(Exception ex){Directory.CreateDirectory(args[1]);File.WriteAllText(Path.Combine(args[1],"report.txt"),ex.ToString());return 1;}}
            if(args.Length>1&&args[0]=="--live-paint-check"){using(MainForm form=new MainForm(new Settings(),true)){form.Show();Application.DoEvents();form.ExercisePaintForTest();using(Bitmap bitmap=new Bitmap(form.ClientSize.Width,form.ClientSize.Height)){using(Graphics graphics=Graphics.FromImage(bitmap))graphics.CopyFromScreen(form.PointToScreen(Point.Empty),Point.Empty,bitmap.Size);bitmap.Save(args[1],System.Drawing.Imaging.ImageFormat.Png);}form.Quit();}return 0;}
